ALTER TABLE public.companies ADD COLUMN contact jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.sellers ADD COLUMN contact jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.plates ADD COLUMN annual_consent_at timestamptz, ADD COLUMN annual_consent_version text, ADD COLUMN annual_consent_amount numeric;
ALTER TABLE public.commissions ADD COLUMN payment_reference text;
COMMENT ON COLUMN public.batches.unit_cost IS 'DEPRECATED: no longer used for new operations; historical data preserved';
COMMENT ON COLUMN public.plates.cost IS 'DEPRECATED: historical cost only';
COMMENT ON COLUMN public.sales.cost IS 'DEPRECATED: historical cost only';
COMMENT ON COLUMN public.settings.plate_cost IS 'DEPRECATED: historical cost only';
CREATE OR REPLACE FUNCTION public.public_plate_state(_code text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.plates%ROWTYPE; BEGIN SELECT * INTO p FROM public.plates WHERE qr_code=upper(trim(_code)); IF NOT FOUND THEN RETURN jsonb_build_object('state','notfound'); END IF; IF p.blocked_by_admin OR p.blocked_by_client THEN RETURN jsonb_build_object('state','blocked'); END IF; IF p.status='available' AND p.company_id IS NULL THEN RETURN jsonb_build_object('state','unlinked','annualPrice',(SELECT subscription_price FROM public.settings WHERE id=true)); END IF; IF p.status='linked' THEN RETURN jsonb_build_object('state','ok'); END IF; RETURN jsonb_build_object('state','notfound'); END $$;
REVOKE ALL ON FUNCTION public.public_plate_state(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_plate_state(text) TO anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.activate_plate(text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.activate_plate(text,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.activate_registered_plate(_code text,_company_name text,_review_url text,_contact jsonb,_accepted boolean,_annual_price numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; configured numeric; company_uuid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso negado.'; END IF; SELECT subscription_price INTO configured FROM public.settings WHERE id=true FOR SHARE; IF _accepted IS DISTINCT FROM true OR _annual_price IS DISTINCT FROM configured THEN RAISE EXCEPTION 'Confirme o aceite do valor anual atual.'; END IF; IF jsonb_typeof(_contact)<>'object' OR octet_length(_contact::text)>3000 OR coalesce(_contact->>'whatsapp','')='' OR coalesce(_contact->>'document','')='' OR coalesce(_contact->>'street','')='' OR coalesce(_contact->>'city','')='' THEN RAISE EXCEPTION 'Complete os dados de cadastro.'; END IF; result:=public.activate_plate(_code,_company_name,_review_url); company_uuid:=(result->>'companyId')::uuid; UPDATE public.companies SET contact=_contact WHERE id=company_uuid AND owner_id=auth.uid(); UPDATE public.plates SET annual_consent_at=now(),annual_consent_version='2026-11-13',annual_consent_amount=configured WHERE qr_code=_code; INSERT INTO public.payments(company_id,sale_id,kind,amount,status) SELECT company_id,id,'plate',amount,'pending' FROM public.sales WHERE plate_id=(SELECT id FROM public.plates WHERE qr_code=_code) ORDER BY created_at DESC LIMIT 1; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.activate_registered_plate(text,text,text,jsonb,boolean,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.activate_registered_plate(text,text,text,jsonb,boolean,numeric) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.confirm_commission_payment(_id uuid,_reference text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.commissions%ROWTYPE; BEGIN IF auth.uid() IS NULL OR NOT public.is_admin() THEN RAISE EXCEPTION 'Acesso negado.'; END IF; IF length(trim(_reference)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Informe a referência do pagamento.'; END IF; SELECT * INTO c FROM public.commissions WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Comissão não encontrada.'; END IF; IF c.status='paid' THEN RETURN jsonb_build_object('ok',true,'already',true); END IF; IF c.status<>'pending' THEN RAISE EXCEPTION 'Comissão não está pendente.'; END IF; IF c.kind='sale' AND NOT EXISTS(SELECT 1 FROM public.sales WHERE id=c.sale_id AND payment_status='paid') THEN RAISE EXCEPTION 'Confirme o recebimento da venda antes de pagar a comissão.'; END IF; IF c.kind='renewal' AND NOT EXISTS(SELECT 1 FROM public.payments WHERE id=c.payment_id AND status='paid') THEN RAISE EXCEPTION 'Confirme o recebimento da renovação antes de pagar a comissão.'; END IF; UPDATE public.commissions SET status='paid',paid_at=now(),payment_reference=trim(_reference) WHERE id=_id; INSERT INTO public.audit_logs(user_id,action,entity,entity_id,details) VALUES(auth.uid(),'commission.pay','commissions',_id::text,jsonb_build_object('reference',trim(_reference),'amount',c.amount)); RETURN jsonb_build_object('ok',true,'already',false); END $$;
REVOKE ALL ON FUNCTION public.confirm_commission_payment(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.confirm_commission_payment(uuid,text) TO authenticated,service_role;